export const featuredRcPlaneIds = ["rc-104-extra-ng-v2-bluewhitesilver", "rc-3000mm-fox-aerobatic-ep-glider-pnp", "rc-twin-otter-80e-super-pnp-day", "rc-plaaf-j-10a-ultra-performance-8s-90mm-edf-jet-pnp", "rc-104-extra-ng-v2-redsilver-scale-ng-scheme", "rc-legacy-100-turbo-bushmaster-bluewhiteyellow-scheme"];

export function getRcPlaneBySlug(slug) {
  return rcPlanes.find((p) => p.slug === slug) || null;
}

export function getFeaturedRcPlanes(limit = 3) {
  const map = new Map(rcPlanes.map((p) => [p.id, p]));
  return featuredRcPlaneIds.map((id) => map.get(id)).filter(Boolean).slice(0, limit);
}

export function getRcPlanesByCategory() {
  const groups = {};
  for (const p of rcPlanes) {
    const cat = p.categories[0] || 'RC Airplane';
    (groups[cat] ||= []).push(p);
  }
  return Object.entries(groups)
    .sort((a, b) => a[0].localeCompare(b[0]))
    .map(([category, items]) => ({
      category,
      items: items.sort((a, b) => b.price_usd - a.price_usd),
    }));
}

export const rcPlaneCategories = [
  ...new Set(rcPlanes.flatMap((p) => p.categories)),
].sort();
